from typing import List

class Solution:
    def totalNumbers(self, digits: List[int]) -> int:
        # Count the frequency of each digit
        count = {}
        for digit in digits:
            if digit in count:
                count[digit] += 1
            else:
                count[digit] = 1

        # Initialize the total count of distinct 3-digit even numbers
        total = 0

        # Iterate over all possible hundreds digits
        for i in range(1, 10):
            # Skip if the hundreds digit is not even
            if i % 2 != 0:
                continue

            # Iterate over all possible tens digits
            for j in range(10):
                # Skip if the tens digit is the same as the hundreds digit or not even
                if j == i or j % 2 != 0:
                    continue

                # Iterate over all possible units digits
                for k in range(10):
                    # Skip if the units digit is the same as the hundreds or tens digit or not even
                    if k == i or k == j or k % 2 != 0:
                        continue

                    # Calculate the number of ways to arrange the digits
                    ways = 1
                    for digit in count:
                        ways *= count[digit]

                    # Subtract 1 from the ways count if there's only one copy of the digit
                    if count[i] == 1:
                        ways -= 1
                    if count[j] == 1:
                        ways -= 1
                    if count[k] == 1:
                        ways -= 1

                    # Update the total count
                    total += ways

        return total
```

This solution works by first counting the frequency of each digit in the input array. It then iterates over all possible hundreds, tens, and units digits to form 3-digit numbers. For each combination of digits, it calculates the number of ways to arrange them and adds it to the total count. If a digit appears only once, it subtracts 1 from the ways count to avoid counting the same number multiple times.

