from typing import List

class Solution:
    def countPartitions(self, nums: List[int]) -> int:
        n = len(nums)
        prefix_sum = [0] * (n + 1)
        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + nums[i]

        def check(x: int) -> bool:
            return (prefix_sum[n] - prefix_sum[x + 1]) - (prefix_sum[x] - prefix_sum[0]) in [0, 2, 4, 6, 8]

        count = 0
        for i in range(n - 1):
            if check(i):
                count += 1
        return count
```

