from typing import List

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        # Create a mapping from value to list of indices
        value_to_indices = {}
        for idx, val in enumerate(elements):
            if val not in value_to_indices:
                value_to_indices[val] = []
            value_to_indices[val].append(idx)

        assigned = []

        for group_size in groups:
            # Find the smallest index element that divides group_size
            best_idx = -1

            # Check all possible values that could divide group_size
            # We iterate through all possible divisors
            for divisor in range(1, int(group_size**0.5) + 1):
                if group_size % divisor == 0:
                    # divisor is a valid element value
                    if divisor in value_to_indices:
                        indices = value_to_indices[divisor]
                        if best_idx == -1 or indices[0] < best_idx:
                            best_idx = indices[0]

                    # Check co-divisor (if different)
                    co_divisor = group_size // divisor
                    if co_divisor != divisor and co_divisor in value_to_indices:
                        indices = value_to_indices[co_divisor]
                        if best_idx == -1 or indices[0] < best_idx:
                            best_idx = indices[0]

            assigned.append(best_idx)

        return assigned
