class Solution:
    def minimumPairRemoval(self, nums: List[int]) -> int:
        if len(nums) <= 1:
            return 0

        # Helper to check if array is non-decreasing
        def is_sorted(arr):
            for i in range(len(arr) - 1):
                if arr[i] > arr[i + 1]:
                    return False
            return True

        # Check if already sorted
        if is_sorted(nums):
            return 0

        operations = 0

        while not is_sorted(nums):
            n = len(nums)
            min_sum = float('inf')
            min_idx = -1

            # Find the leftmost adjacent pair with minimum sum
            for i in range(n - 1):
                s = nums[i] + nums[i + 1]
                if s < min_sum:
                    min_sum = s
                    min_idx = i

            # Replace the pair with their sum
            nums[min_idx] = min_sum
            nums.pop(min_idx + 1)
            operations += 1

        return operations
