from typing import List

class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        n = len(grid)
        m = len(grid[0])

        # Collect all cells in zigzag traversal order
        all_cells = []

        for r in range(n):
            if r % 2 == 0:  # Even row: traverse right (left to right)
                for c in range(m):
                    all_cells.append(grid[r][c])
            else:  # Odd row: traverse left (right to left)
                for c in range(m - 1, -1, -1):
                    all_cells.append(grid[r][c])

        # Skip every alternate cell: keep indices 0, 2, 4, ...
        return all_cells[::2]
